-- Additive rollout. Apply on release; old games are deliberately not enqueued.
create table public.game_achievement_release (
  singleton boolean primary key default true check(singleton),
  launched_at timestamptz not null default now()
);
alter table public.game_achievement_release enable row level security;
revoke all on public.game_achievement_release from anon, authenticated;
grant select on public.game_achievement_release to service_role;

create table public.game_achievement_rules (
  key text primary key,
  badge_id uuid not null unique references public.badges(id) on delete cascade
);
alter table public.game_achievement_rules enable row level security;
revoke all on public.game_achievement_rules from anon, authenticated;
grant select on public.game_achievement_rules to service_role;

alter table public.student_badges add column achievement_evidence jsonb;
create table public.game_achievement_scans (
  student_id uuid not null references public.students(id) on delete cascade,
  source_id text not null,
  internal_game_id uuid references public.internal_chess_games(id) on delete cascade,
  started_at timestamptz not null,
  completed_at timestamptz not null,
  opponent_key text not null,
  won boolean not null,
  payload jsonb,
  processed_at timestamptz,
  validation_error text,
  primary key(student_id,source_id)
);
create index game_achievement_scans_pending on public.game_achievement_scans(student_id,completed_at,source_id) where processed_at is null;
create index game_achievement_scans_streak on public.game_achievement_scans(student_id,completed_at desc,source_id desc);
create index game_achievement_scans_internal on public.game_achievement_scans(internal_game_id) where internal_game_id is not null;
alter table public.game_achievement_scans enable row level security;
revoke all on public.game_achievement_scans from anon,authenticated;
grant select,insert,update on public.game_achievement_scans to service_role;

create function public.enqueue_game_achievements() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
  if new.started_at >= (select launched_at from public.game_achievement_release where singleton)
     and new.initial_fen='rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1'
     and coalesce(new.takeback_count,0)=0 and jsonb_array_length(new.moves)>0 then
    values(new.player_id,'academy:'||new.id,new.id,new.started_at,new.completed_at,
      'academy:'||new.opponent_type||':'||new.opponent_id,new.result='win')
    on conflict do nothing;
  end if;
  return new;
end $$;
revoke all on function public.enqueue_game_achievements() from public,anon,authenticated;
grant execute on function public.enqueue_game_achievements() to service_role;
create trigger enqueue_game_achievements after insert on public.internal_chess_games
for each row execute function public.enqueue_game_achievements();

-- Completion, badge, XP, coins (existing XP trigger), and evidence are one transaction.
-- Only trusted server code may submit detections; no browser RPC access.
create function public.complete_game_achievement_scan(p_student_id uuid,p_source_id text,p_hits jsonb)
returns integer language plpgsql security invoker set search_path='' as $$
declare scan public.game_achievement_scans%rowtype; hit jsonb; rule record;
  awarded uuid; award_count integer:=0; streak integer:=0; previous record;
begin
  perform pg_advisory_xact_lock(hashtextextended('game-achievements:'||p_student_id,0));
  select * into scan from public.game_achievement_scans where student_id=p_student_id and source_id=p_source_id for update;
  if not found or scan.processed_at is not null then return 0; end if;
  if scan.started_at < (select launched_at from public.game_achievement_release where singleton) then
    update public.game_achievement_scans set processed_at=now(),payload=null where student_id=p_student_id and source_id=p_source_id;
    return 0;
  end if;
  if p_hits is null or jsonb_typeof(p_hits)<>'array' or jsonb_array_length(p_hits)>80 then raise exception 'Invalid achievement evidence'; end if;
  -- Academy history is complete. A capped Lichess import cannot prove a streak.
  if scan.won and scan.internal_game_id is not null then
    for previous in select won,opponent_key from public.game_achievement_scans
      where student_id=p_student_id and internal_game_id is not null and (completed_at,source_id)<=(scan.completed_at,scan.source_id)
      order by completed_at desc,source_id desc limit 20
    loop
      exit when not previous.won or previous.opponent_key<>scan.opponent_key;
      streak:=streak+1;
    end loop;
    if streak>=10 then p_hits:=p_hits||jsonb_build_array(jsonb_build_object('key','adoption','ply',0)); end if;
    if streak>=20 then p_hits:=p_hits||jsonb_build_array(jsonb_build_object('key','double-adoption','ply',0)); end if;
  end if;
  for hit in select value from jsonb_array_elements(p_hits) loop
    select b.id,b.name,b.xp_value into rule from public.game_achievement_rules r join public.badges b on b.id=r.badge_id where r.key=hit->>'key';
    if not found then raise exception 'Unknown achievement'; end if;
    awarded:=null;
    values(p_student_id,rule.id,'Automatically earned in a completed game.',
      jsonb_build_object('sourceId',scan.source_id,'ply',coalesce((hit->>'ply')::integer,0),'fen',hit->>'fen','completedAt',scan.completed_at))
    on conflict(student_id,badge_id) do nothing returning id into awarded;
    if awarded is not null then
      update public.students set total_xp=coalesce(total_xp,0)+rule.xp_value where id=p_student_id;
      values(p_student_id,'badge_earned',rule.name,'Earned '||rule.xp_value||' XP and '||rule.xp_value||' Academy Coins.');
      award_count:=award_count+1;
    end if;
  end loop;
  update public.game_achievement_scans set processed_at=now(),payload=null where student_id=p_student_id and source_id=p_source_id;
  return award_count;
end $$;
revoke all on function public.complete_game_achievement_scan(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.complete_game_achievement_scan(uuid,text,jsonb) to service_role;
